/**
 * DesInspect — Selector Engine
 * 
 * Generates robust CSS selectors for elements that survive minor DOM changes.
 * Priority order: #id > [data-testid] > tag.class path > nth-child path > XPath fallback.
 * Includes fragility detection to warn users about unstable selectors.
 */

const SelectorEngine = (() => {

  // Class name patterns that look auto-generated (frameworks, CSS-in-JS, etc.)
  const FRAGILE_CLASS_PATTERNS = [
    /^css-[a-z0-9]+$/i,          // Emotion
    /^sc-[a-z]+$/i,              // styled-components
    /^_[a-zA-Z0-9]{5,}$/,        // CSS Modules
    /^jsx-[0-9]+$/,              // styled-jsx
    /^svelte-[a-z0-9]+$/i,       // Svelte
    /^tw-[a-z0-9]+$/i,           // Tailwind JIT artifacts
    /^[a-z]{1,3}[A-Z][a-zA-Z0-9]{4,}$/, // Minified class names
    /^[a-f0-9]{6,}$/,            // Hash-based classes
  ];

  // Stable attribute selectors to prefer
  const STABLE_ATTRIBUTES = [
    'data-testid',
    'data-cy',
    'data-test',
    'data-id',
    'role',
    'aria-label',
    'name',
    'type',
  ];

  /**
   * Generate the best available selector for an element.
   * Returns an object with the selector string, type, and fragility assessment.
   * 
   * @param {HTMLElement} element
   * @returns {{ selector: string, type: string, fragile: boolean, warning: string|null }}
   */
  function generate(element) {
    // Skip non-element nodes
    if (!element || element.nodeType !== Node.ELEMENT_NODE) {
      return { selector: null, type: 'none', fragile: true, warning: 'Not a valid element' };
    }

    // 1. Try unique ID
    if (element.id && !isFragileId(element.id)) {
      const selector = `#${CSS.escape(element.id)}`;
      if (isUnique(selector)) {
        return { selector, type: 'id', fragile: false, warning: null };
      }
    }

    // 2. Try stable data attributes
    for (const attr of STABLE_ATTRIBUTES) {
      const value = element.getAttribute(attr);
      if (value) {
        const selector = `[${attr}="${CSS.escape(value)}"]`;
        if (isUnique(selector)) {
          return { selector, type: 'attribute', fragile: false, warning: null };
        }
      }
    }

    // 3. Try tag + stable classes
    const stableClasses = getStableClasses(element);
    if (stableClasses.length > 0) {
      const selector = `${element.tagName.toLowerCase()}.${stableClasses.map(c => CSS.escape(c)).join('.')}`;
      if (isUnique(selector)) {
        return { selector, type: 'class', fragile: false, warning: null };
      }
    }

    // 4. Build a path selector (walk up the DOM)
    const pathSelector = buildPathSelector(element);
    if (pathSelector && isUnique(pathSelector.selector)) {
      return pathSelector;
    }

    // 5. nth-child path as last CSS resort
    const nthSelector = buildNthChildPath(element);
    if (nthSelector && isUnique(nthSelector)) {
      return {
        selector: nthSelector,
        type: 'nth-child',
        fragile: true,
        warning: 'Positional selector — may break if elements change.'
      };
    }

    // 6. XPath fallback
    const xpath = buildXPath(element);
    return {
      selector: xpath,
      type: 'xpath',
      fragile: true,
      warning: 'Using XPath — may break if page structure changes.'
    };
  }

  /**
   * Find an element on the page using a selector generated by this engine.
   * Handles both CSS selectors and XPath.
   * 
   * @param {{ selector: string, type: string }} selectorInfo
   * @returns {HTMLElement|null}
   */
  function find(selectorInfo) {
    if (!selectorInfo || !selectorInfo.selector) return null;

    if (selectorInfo.type === 'xpath') {
      const result = document.evaluate(
        selectorInfo.selector,
        document,
        null,
        XPathResult.FIRST_ORDERED_NODE_TYPE,
        null
      );
      return result.singleNodeValue;
    }

    try {
      return document.querySelector(selectorInfo.selector);
    } catch {
      return null;
    }
  }

  // ─── Internal Helpers ─────────────────────────────────────────────────────

  function isUnique(selector) {
    try {
      return document.querySelectorAll(selector).length === 1;
    } catch {
      return false;
    }
  }

  function isFragileId(id) {
    // IDs that look auto-generated
    return /^[a-f0-9]{8,}$/i.test(id) ||
           /^:r[0-9]+:$/.test(id) ||   // React
           /^ember[0-9]+$/.test(id) ||  // Ember
           /^rc-[0-9]+/.test(id);       // Ant Design
  }

  function getStableClasses(element) {
    return Array.from(element.classList).filter(cls => {
      return !FRAGILE_CLASS_PATTERNS.some(pattern => pattern.test(cls));
    });
  }

  function buildPathSelector(element, maxDepth = 4) {
    const parts = [];
    let current = element;
    let depth = 0;
    let fragile = false;

    while (current && current !== document.body && depth < maxDepth) {
      let part = current.tagName.toLowerCase();

      // Add ID if stable
      if (current.id && !isFragileId(current.id)) {
        part = `#${CSS.escape(current.id)}`;
        parts.unshift(part);
        break; // ID is unique enough anchor
      }

      // Add stable classes
      const stableClasses = getStableClasses(current);
      if (stableClasses.length > 0) {
        part += '.' + stableClasses.slice(0, 2).map(c => CSS.escape(c)).join('.');
      } else {
        fragile = true;
      }

      parts.unshift(part);
      current = current.parentElement;
      depth++;
    }

    const selector = parts.join(' > ');
    if (isUnique(selector)) {
      return {
        selector,
        type: 'path',
        fragile,
        warning: fragile
          ? 'Fragile selector — may break if layout changes.'
          : null
      };
    }

    return null;
  }

  function buildNthChildPath(element) {
    const parts = [];
    let current = element;

    while (current && current !== document.documentElement) {
      if (current === document.body) {
        parts.unshift('body');
        break;
      }

      const parent = current.parentElement;
      if (!parent) break;

      const children = Array.from(parent.children);
      const index = children.indexOf(current) + 1;
      parts.unshift(`${current.tagName.toLowerCase()}:nth-child(${index})`);
      current = parent;
    }

    return parts.join(' > ');
  }

  function buildXPath(element) {
    const parts = [];
    let current = element;

    while (current && current.nodeType === Node.ELEMENT_NODE) {
      let index = 1;
      let sibling = current.previousElementSibling;

      while (sibling) {
        if (sibling.tagName === current.tagName) index++;
        sibling = sibling.previousElementSibling;
      }

      parts.unshift(`${current.tagName.toLowerCase()}[${index}]`);
      current = current.parentElement;
    }

    return '/' + parts.join('/');
  }

  return {
    generate,
    find,
    isUnique,
  };
})();
